class MemoryStore:
    def __init__(self):
        self.tables = {}
        self.minted = 0

    def persist(self, op, entity, data):
        rows = self.tables.setdefault(entity, {})
        if op == "create":
            row = dict(_plain(data))
            if not row.get("id"):
                self.minted += 1
                row["id"] = entity + "-" + str(self.minted)
            rows[row["id"]] = row
            return True, dict(row)
        key = data if isinstance(data, str) else _plain(data).get("id")
        if key not in rows:
            return False, {"error": entity + " " + str(key) + " not found", "code": "not-found"}
        if op == "delete":
            del rows[key]
            return True, {"id": key, "deleted": True}
        rows[key].update(_plain(data))
        return True, dict(rows[key])

    def fetch(self, entity, keep):
        rows = [dict(r) for r in self.tables.get(entity, {}).values() if keep is None or keep(dict(r))]
        rows.sort(key=lambda r: (0, r["createdAt"], r["id"]) if "createdAt" in r else (1, 0, r["id"]))
