class _Router:
    def __init__(self):
        self.traits = {}
        self.handles = {}
        self.rows = []
        self.log = []

    def add(self, key, trait):
        self.traits[key] = trait

    def row(self, source, event, target, trigger, guard, mapping):
        self.rows.append((source, event, target, trigger, guard, mapping))

    def targets(self, source, event, payload, completion):
        return [{"trait": target, "event": trigger, "payload": mapping(payload) if mapping else payload, "source": payload,
                 "guard": guard, "fans": False, "completion": completion}
                for (s, e, target, trigger, guard, mapping) in self.rows if s == source and e == event]

    def dispatch(self, trait, event, payload):
        queue = deque([{"trait": trait, "event": event, "payload": payload, "source": payload, "guard": None, "fans": True, "completion": False}])
        seen = set()
        steps = 0
        while queue:
            item = queue.popleft()
            t = self.traits[item["trait"]]
            key = json.dumps([item["trait"], item["event"], t.state, item["payload"], _plain(t.entity)], sort_keys=True, default=str)
            if not item["completion"] and key in seen:
                continue
            if item["guard"] is not None and not item["guard"](item["source"]):
                continue
            if steps >= 2000:
                break
            steps += 1
            seen.add(key)
            n = len(t.emitted)
            self.deliver(item["trait"], item["event"], item["payload"])
            own, fanned = [], []
            if item["fans"]:
                fanned += self.targets(item["trait"], item["event"], item["payload"], False)
            for emitted in t.emitted[n:]:
                ev, out = emitted[0], _plain(emitted[1])
                completion = len(emitted) > 2 and emitted[2]
                self.log.append((item["trait"], ev, out))
                if ev in self.handles[item["trait"]].get(t.state, ()):
                    own.append({"trait": item["trait"], "event": ev, "payload": out, "source": out, "guard": None, "fans": False, "completion": completion})
                fanned += self.targets(item["trait"], ev, out, completion)
            queue.extendleft(reversed(own))
            queue.extend(fanned)
