    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, float) and v - v == 0 and v == int(v): return str(int(v))
    if isinstance(v, (int, float, str)): return str(v)
    raise TypeError('expected string, number or boolean')


class T:
    def __init__(self, entity: Rec, ports=None):
        self.state = "idle"
        self.entity = entity
        self.ports = ports
        self.emitted: list[tuple[str, object]] = []

    def emit(self, event, payload):
        self.emitted.append((event, payload))

    def on_init(self, payload=None) -> None:
        if self.state == "idle":
            self.state = "idle"

    def on_go(self, payload: TGOPayload) -> None:
        if self.state == "idle":
            self.entity.s = "".join(_text(v_) for v_ in ["{{0}} {{type}} \"q\" \\ é\n", payload.x])
            self.entity.o = {"a-b": "v", "c": payload.x}
            self.emit("DONE", TDONEPayload(s=self.entity.s))
            self.state = "idle"
